// Función para ejecutar un Test Step y obtener la respuesta
def runTestStep(testStepName) {
    def testStep = testRunner.testCase.getTestStepByName(testStepName)

    if (testStep == null) {
        log.error "Test Step '${testStepName}' no encontrado"
        return null
    }

    def testStepResult = testStep.run(testRunner, context)

    if (testStepResult.getStatus().toString() == "FAILED") {
        log.error "El Test Step '${testStepName}' falló"
        return null
    } else {
        log.info "El Test Step '${testStepName}' se ejecutó correctamente"
    }

    def responseContent = testStepResult.getResponse().getContentAsString()
    log.info "Respuesta del Test Step '${testStepName}': ${responseContent}"

    return responseContent
}

// Función para extraer un valor de una respuesta JSON
def extractValueFromJsonResponse(response, key) {
    def jsonSlurper = new groovy.json.JsonSlurper()
    def jsonResponse = jsonSlurper.parseText(response)
    return jsonResponse[key]
}

